importScripts('ort.wasm.min.js','matcher.js','scene.js');
const cache=new Map();let readyPromise;
async function assets(name,manifest){const chunks=[];for(let i=0;i<manifest[name].length;i++){const part=manifest[name][i];postMessage({message:`Loading ${name}: part ${i+1} / ${manifest[name].length}…`});const r=await fetch(part.file);if(!r.ok)throw Error(`Missing engine file ${part.file}. Upload the entire dist folder.`);const bytes=await r.arrayBuffer();const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');if(digest!==part.sha256)throw Error(`Engine file ${part.file} is incomplete. Refresh after deployment finishes.`);chunks.push(new Uint8Array(bytes))}let n=chunks.reduce((s,b)=>s+b.length,0),out=new Uint8Array(n),offset=0;for(const chunk of chunks){out.set(chunk,offset);offset+=chunk.length}return out}
function ready(){return readyPromise||(readyPromise=(async()=>{const r=await fetch('assets.json');if(!r.ok)throw Error('Matching engine manifest is missing.');const manifest=await r.json();const cvCode=await assets('opencv',manifest);const url=URL.createObjectURL(new Blob([cvCode],{type:'text/javascript'}));try{importScripts(url)}finally{URL.revokeObjectURL(url)}const {engine}=await new Promise(resolve=>cv.Mat?resolve({engine:cv}):cv.then(c=>resolve({engine:c})));ort.env.wasm.numThreads=1;ort.env.wasm.proxy=false;ort.env.wasm.wasmPaths={mjs:new URL('ort-wasm-simd-threaded.mjs',location.href).href};ort.env.wasm.wasmBinary=await assets('wasm',manifest);const model=await assets('model',manifest);postMessage({message:'Preparing scene model…'});const session=await ort.InferenceSession.create(model,{executionProviders:['wasm'],graphOptimizationLevel:'all'});return {engine,session}})())}
async function sceneFeatures(session,rgba,width,height){
 const source=new OffscreenCanvas(width,height);source.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(rgba),width,height),0,0);const c=new OffscreenCanvas(224,224),ctx=c.getContext('2d',{willReadFrequently:true});const views=[[0,0,1],[0,0,.6],[1,0,.6],[0,1,.6],[1,1,.6],[.5,.5,.6]],vectors=[];let regions;
 for(const [x,y,size] of views){const x0=Math.round(x*width*(1-size)),y0=Math.round(y*height*(1-size)),x1=Math.round(x*width*(1-size)+width*size),y1=Math.round(y*height*(1-size)+height*size);ctx.drawImage(source,x0,y0,x1-x0,y1-y0,0,0,224,224);const pixels=ctx.getImageData(0,0,224,224).data,input=new Float32Array(3*224*224),mean=[.485,.456,.406],std=[.229,.224,.225];for(let k=0;k<3;k++)for(let i=0;i<224*224;i++)input[k*224*224+i]=(pixels[4*i+k]/255-mean[k])/std[k];const t=new ort.Tensor('float32',input,[1,3,224,224]);const output=await session.run({pixel_values:t});const tensor=output.last_hidden_state,v=Float32Array.from(tensor.data.slice(0,384));let norm=Math.sqrt(v.reduce((s,x)=>s+x*x,0));for(let k=0;k<v.length;k++)v[k]/=norm||1;vectors.push(v);if(size===1)regions=SceneMatcher.regions(tensor.data);t.dispose();for(const value of Object.values(output))value.dispose()}
 return {vectors,regions};
}
self.onmessage=async({data})=>{const {request,type}=data;try{const {engine,session}=await ready();if(type==='ready'){postMessage({request,ok:true});return}if(type==='clear'){cache.clear();postMessage({request,ok:true});return}if(type==='extract'){const rgba=new Uint8Array(data.rgba);cache.set(data.id,{local:RobustMatcher.extract(engine,rgba,data.width,data.height),scene:await sceneFeatures(session,rgba,data.width,data.height)});postMessage({request,ok:true});return}if(type==='rank'){let done=0;const matrix=[],total=data.docs.length*data.uploads.length;for(const id of data.docs){const a=cache.get(id),row=[];for(const uid of data.uploads){const b=cache.get(uid);row.push({...RobustMatcher.compare(engine,a.local,b.local),scene:SceneMatcher.similarity(a.scene.vectors,b.scene.vectors),objectScore:SceneMatcher.similarity(a.scene.regions,b.scene.regions)});if(++done%15===0)postMessage({progress:done,total})}matrix.push(row)}postMessage({request,ranks:SceneMatcher.rank(matrix,data.docs)});return}throw Error('Unknown operation')}catch(e){postMessage({request,error:e.message||String(e)})}};
